package de.lazytv.pro.playlist;
import android.view.*;import android.widget.*;import java.util.*;import de.lazytv.pro.R;
public class PlaylistAdapter extends BaseAdapter {private final List<Playlist> items=new ArrayList<>();private String activeId="";public void submit(List<Playlist> list,String active){items.clear();items.addAll(list);activeId=active==null?"":active;notifyDataSetChanged();}public int getCount(){return items.size();}public Playlist getItem(int p){return items.get(p);}public long getItemId(int p){return p;}public View getView(int pos,View v,ViewGroup parent){if(v==null)v=LayoutInflater.from(parent.getContext()).inflate(R.layout.item_playlist,parent,false);Playlist p=getItem(pos);((TextView)v.findViewById(R.id.playlist_name)).setText(p.getName());String type=label(p.getType());String status=p.getId().equals(activeId)?"  •  ACTIVE":"";((TextView)v.findViewById(R.id.playlist_type)).setText(type+status);((TextView)v.findViewById(R.id.playlist_endpoint)).setText(endpoint(p));return v;}private String endpoint(Playlist p){if(p.getType()==PlaylistType.M3U_FILE)return"Ruajtur në pajisje • zgjidh për ta hapur";if(p.getType()==PlaylistType.XTREAM_CODES)return p.getUrl()+"  •  "+p.getUsername();if(p.getType()==PlaylistType.STALKER_PORTAL)return p.getUrl()+"  •  "+p.getMacAddress();return p.getUrl();}private String label(PlaylistType t){switch(t){case FREE_TV:return"FREE TV";case M3U_URL:return"M3U URL";case M3U_FILE:return"M3U FILE • PREMIUM";case XTREAM_CODES:return"XTREAM CODES";case STALKER_PORTAL:return"STALKER / PORTAL";default:return t.name();}}}
